-- TX-1: Remove stale candidate2 (Dax Alexander - he's in the runoff, not the R nominee)
UPDATE house_races SET candidate2_name = 'N. Moran', candidate2_party = 'R'
WHERE state_code = 'TX' AND district = '1';

-- TX-5: Remove stale candidate2 (Chelsey Hockett - she's in the runoff, not the R nominee)
UPDATE house_races SET candidate2_name = 'Lance Gooden', candidate2_party = 'R'
WHERE state_code = 'TX' AND district = '5';

-- TX-7: Remove stale candidate1 (Alexander Hale - he's in the runoff)
UPDATE house_races SET candidate1_name = 'Lizzie Fletcher', candidate1_party = 'D'
WHERE state_code = 'TX' AND district = '7';

-- TX-9: Remove stale candidate1 (Briscoe Cain - he's in the runoff)
UPDATE house_races SET candidate1_name = 'Lorenzo Gutierrez', candidate1_party = 'D'
WHERE state_code = 'TX' AND district = '9';

-- TX-14: Remove stale candidate2 (Richard Davis - he's in the D runoff, no R candidate yet)
UPDATE house_races SET candidate2_name = NULL, candidate2_party = NULL
WHERE state_code = 'TX' AND district = '14';

SELECT state_code, district, status, candidate1_name, candidate1_party, candidate2_name, candidate2_party 
FROM house_races WHERE state_code = 'TX' AND district IN ('1','5','7','9','14') ORDER BY CAST(district AS UNSIGNED);

